325	    #[inductive(consume_end)]
326	    fn consume_end_inductive(pre: Self, post: Self, perm: cell::PointsTo<T>) {
327	        let head = pre.consumer.get_Consuming_0();
328	        let next_head = FifoQueue::State::<T>::inc_wrap(head, pre.len());
329	        assert forall|i: nat| 0 <= i && i < post.len() ==> post.valid_storage_at_idx(i) by {
330	            if 0 <= i && i < post.len() {
331	                if i == head {
332	                    assert(post.storage.dom().contains(i));
333	                } else {
334	                    assert(pre.valid_storage_at_idx(i));
335	                    assert(post.valid_storage_at_idx(i));
336	                }
337	            }
338	        }
